-- Operator-declared Fleet configuration and blocked proposals only.
-- This migration does not enroll observers, attest Git/state, issue Fleet proof
-- sets, sign plans, grant execution or publish financial evidence.
CREATE TABLE fleet_configuration_declarations (
 tenant_id text NOT NULL,id text NOT NULL,registration_id text NOT NULL,registration_version bigint NOT NULL,workload_id text NOT NULL,version bigint NOT NULL CHECK(version>0),
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,registration_id,version),FOREIGN KEY(tenant_id,registration_id,registration_version) REFERENCES fleet_history_registrations(tenant_id,id,version),CHECK(octet_length(raw_document)<=32768)
);
CREATE TABLE fleet_configuration_proposals (
 tenant_id text NOT NULL,id text NOT NULL,registration_id text NOT NULL,registration_version bigint NOT NULL,workload_id text NOT NULL,declaration_id text NOT NULL,scope_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,registration_id,registration_version) REFERENCES fleet_history_registrations(tenant_id,id,version),FOREIGN KEY(tenant_id,declaration_id) REFERENCES fleet_configuration_declarations(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES fleet_history_scopes(tenant_id,id),CHECK(octet_length(raw_document)<=65536)
);
CREATE INDEX fleet_configuration_declarations_page ON fleet_configuration_declarations(tenant_id,registration_id,created_at DESC,id DESC);
CREATE INDEX fleet_configuration_proposals_page ON fleet_configuration_proposals(tenant_id,registration_id,created_at DESC,id DESC);
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fleet_configuration_declarations','fleet_configuration_proposals'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK(tenant_id=current_setting(''app.tenant_id'',true))',tab);
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION public.deny_evidence_mutation()',tab||'_immutable',tab);
 END LOOP;END $$;
GRANT SELECT ON fleet_configuration_declarations,fleet_configuration_proposals TO finops_api,finops_ingester;
GRANT INSERT ON fleet_configuration_declarations,fleet_configuration_proposals TO finops_api;

-- INVOKER helpers: reads retain forced tenant RLS and grant no UPDATE/row-lock
-- privilege to the API. The existing narrow source lock holds FOR SHARE.
CREATE FUNCTION fleet_configuration_registration(p_tenant text,p_registration text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE r jsonb;s jsonb;v bigint;BEGIN
 IF p_tenant IS NULL OR p_tenant='' OR p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) OR coalesce(p_registration,'')='' THEN RAISE EXCEPTION 'fleet configuration tenant or registration differs'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant||':dependency-graph',0));
 PERFORM public.fleet_history_lock(p_tenant,p_registration);
 SELECT document INTO r FROM public.fleet_history_registrations WHERE tenant_id=p_tenant AND id=p_registration ORDER BY version DESC LIMIT 1;
 IF r IS NULL THEN RETURN NULL;END IF;
 IF NOT public.fleet_history_source_lock(p_tenant,r->>'source_id') THEN RETURN NULL;END IF;
 SELECT document,version INTO s,v FROM public.source_registrations WHERE tenant_id=p_tenant AND id=r->>'source_id';
 IF s IS NULL OR s->>'enabled' IS DISTINCT FROM 'true' OR coalesce((s->>'revoked')::boolean,false) OR s->>'region' IS DISTINCT FROM r->'binding'->>'region' OR NOT coalesce(s->>'payer_account_id'=r->'binding'->>'account_id' OR s->'usage_account_ids' ? (r->'binding'->>'account_id'),false) OR public.fleet_history_source_config(s) IS DISTINCT FROM r->>'source_config_hash' OR v<(r->>'source_registration_version')::bigint OR NOT EXISTS(SELECT 1 FROM public.entities WHERE tenant_id=p_tenant AND kind='workloads' AND id=r->'binding'->>'workload_id') THEN RETURN NULL;END IF;
 RETURN r;
END $$;

-- Exact issued scope references are re-resolved under current guards. Old
-- snapshots remain immutable, but cannot borrow a changed registration,
-- definition, source config or reassigned activity resource for a new proposal.
CREATE FUNCTION fleet_configuration_scope_sources(p_tenant text,p_registration text,p_scope text,p_as_of timestamptz) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE r jsonb;sc public.fleet_history_scopes%ROWTYPE;d public.fleet_demand_definitions%ROWTYPE;ref record;s jsonb;checkpoint jsonb;v bigint;status text;states jsonb:='[]'::jsonb;n integer:=0;aws_seen boolean:=false;activity_seen boolean:=false;BEGIN
 r:=public.fleet_configuration_registration(p_tenant,p_registration);
 IF r IS NULL OR p_as_of IS NULL OR abs(extract(epoch FROM clock_timestamp()-p_as_of))>30 THEN RETURN NULL;END IF;
 SELECT * INTO sc FROM public.fleet_history_scopes WHERE tenant_id=p_tenant AND id=p_scope;
 IF sc.id IS NULL OR sc.registration_id IS DISTINCT FROM p_registration OR sc.registration_version IS DISTINCT FROM (r->>'version')::bigint OR sc.document->'binding' IS DISTINCT FROM r->'binding' OR sc.document->>'asg_arn' IS DISTINCT FROM r->>'asg_arn' OR sc.document->>'fleet_id' IS DISTINCT FROM r->>'fleet_id' OR sc.document->>'status' IS DISTINCT FROM 'BLOCKED' OR sc.document->>'membership_status' IS DISTINCT FROM 'INTERVAL_OWNERSHIP_UNPROVEN' THEN RETURN NULL;END IF;
 IF sc.document->>'registration_hash' IS DISTINCT FROM (SELECT content_hash FROM public.fleet_history_registrations WHERE tenant_id=p_tenant AND id=p_registration AND version=sc.registration_version) OR (sc.document->>'observation_count')::bigint IS DISTINCT FROM (SELECT count(*) FROM public.fleet_history_scope_references WHERE tenant_id=p_tenant AND scope_id=p_scope AND kind='OBSERVATION') OR coalesce((sc.document->>'selected_observation_count')::bigint,-1) NOT BETWEEN 0 AND (sc.document->>'observation_count')::bigint THEN RETURN NULL;END IF;
 SELECT * INTO d FROM public.fleet_demand_definitions WHERE tenant_id=p_tenant AND id=sc.definition_id ORDER BY version DESC LIMIT 1;
 IF d.id IS NULL OR d.version IS DISTINCT FROM sc.definition_version OR d.registration_id IS DISTINCT FROM p_registration OR d.registration_version IS DISTINCT FROM sc.registration_version OR d.document->'binding' IS DISTINCT FROM r->'binding' OR d.document->>'metric' IS DISTINCT FROM 'activity.Completed' OR d.document->>'value_field' IS DISTINCT FROM 'COMPLETED' OR d.document->>'temporality' IS DISTINCT FROM 'DELTA' OR d.document->>'source_system' IS DISTINCT FROM 'ACTIVITY_SOURCE' OR d.content_hash IS DISTINCT FROM sc.document->>'definition_hash' THEN RETURN NULL;END IF;
 -- Detect a later ingested point/correction inside the selected historical
 -- interval. Equal current snapshots never establish interval ownership.
 IF EXISTS(SELECT 1 FROM public.fleet_history_observations o WHERE o.tenant_id=p_tenant AND o.registration_id=p_registration AND o.registration_version=sc.registration_version AND o.observed_at>=(sc.document->>'start')::timestamptz AND o.observed_at<=(sc.document->>'end')::timestamptz AND NOT EXISTS(SELECT 1 FROM public.fleet_history_scope_references f WHERE f.tenant_id=p_tenant AND f.scope_id=p_scope AND f.kind='OBSERVATION' AND f.reference_id=o.id AND f.document->>'hash'=o.content_hash)) THEN RETURN NULL;END IF;
 FOR ref IN SELECT document FROM public.fleet_history_scope_references WHERE tenant_id=p_tenant AND scope_id=p_scope AND kind='SOURCE_STATE' ORDER BY reference_id LIMIT 1025 LOOP
  n:=n+1;IF n>1024 OR ref.document->'binding' IS DISTINCT FROM r->'binding' THEN RETURN NULL;END IF;
  IF ref.document->>'source_system'='AWS_SOURCE_CONNECTION' THEN
   IF NOT public.fleet_history_source_lock(p_tenant,ref.document->>'source_id') THEN RETURN NULL;END IF;
   SELECT document,version INTO s,v FROM public.source_registrations WHERE tenant_id=p_tenant AND id=ref.document->>'source_id';
   IF s IS NULL OR s->>'enabled' IS DISTINCT FROM 'true' OR coalesce((s->>'revoked')::boolean,false) OR public.fleet_history_source_config(s) IS DISTINCT FROM ref.document->>'config_hash' OR s->>'region' IS DISTINCT FROM r->'binding'->>'region' OR NOT coalesce(s->>'payer_account_id'=r->'binding'->>'account_id' OR s->'usage_account_ids' ? (r->'binding'->>'account_id'),false) OR v<coalesce((ref.document->>'source_registration_version')::bigint,0) THEN RETURN NULL;END IF;
   IF ref.document->>'source_id'=r->>'source_id' THEN aws_seen:=true;IF public.fleet_history_source_config(s) IS DISTINCT FROM r->>'source_config_hash' THEN RETURN NULL;END IF;END IF;
   SELECT document INTO checkpoint FROM public.source_checkpoints WHERE tenant_id=p_tenant AND source_id=ref.document->>'source_id' AND checkpoint_key='status';
   status:=CASE WHEN checkpoint->>'status' IS DISTINCT FROM 'HEALTHY' OR checkpoint->>'config_hash' IS DISTINCT FROM public.fleet_history_source_config(s) OR checkpoint->>'last_sync_at' IS NULL OR (checkpoint->>'last_sync_at')::timestamptz>p_as_of+interval '5 seconds' OR p_as_of-(checkpoint->>'last_sync_at')::timestamptz>interval '5 minutes' THEN 'DEGRADED' ELSE 'ACTIVE' END;
   states:=states||jsonb_build_array(jsonb_build_object('source_id',ref.document->>'source_id','source_system','AWS_SOURCE_CONNECTION','source_registration_version',v,'config_hash',public.fleet_history_source_config(s),'binding',r->'binding','status',status,'checked_at',p_as_of));
  ELSIF ref.document->>'source_system'='ACTIVITY_SOURCE' THEN
   SELECT document INTO s FROM public.activity_sources WHERE tenant_id=p_tenant AND id=ref.document->>'source_id';
   IF s IS NULL OR s->>'enabled' IS DISTINCT FROM 'true' OR ref.document->>'source_id' IS DISTINCT FROM d.source_id OR public.fleet_history_json_hash(s) IS DISTINCT FROM d.document->>'source_config_hash' OR public.fleet_history_json_hash(s) IS DISTINCT FROM ref.document->>'config_hash' OR s->>'workload_id' IS DISTINCT FROM r->'binding'->>'workload_id' OR s->>'account_id' IS DISTINCT FROM r->'binding'->>'account_id' OR s->>'region' IS DISTINCT FROM r->'binding'->>'region' OR s->'metric_definition'->>'id' IS DISTINCT FROM d.document->>'metric_definition_id' OR s->'metric_definition'->>'version' IS DISTINCT FROM d.document->>'metric_definition_version' OR s->'metric_definition'->>'unit' IS DISTINCT FROM d.document->>'unit' OR NOT EXISTS(SELECT 1 FROM public.entities WHERE tenant_id=p_tenant AND kind='resources' AND id=s->>'resource_id' AND document->>'workload_id'=r->'binding'->>'workload_id' AND document->>'provider'='AWS' AND document->>'provider_resource_id'=s->>'provider_resource_id' AND document->>'account_id'=s->>'account_id' AND document->>'region'=s->>'region') THEN RETURN NULL;END IF;
   activity_seen:=true;
   states:=states||jsonb_build_array(jsonb_build_object('source_id',d.source_id,'source_system','ACTIVITY_SOURCE','config_hash',public.fleet_history_json_hash(s),'binding',r->'binding','status','ACTIVE','checked_at',p_as_of));
  ELSE RETURN NULL;END IF;
 END LOOP;
 IF NOT aws_seen OR NOT activity_seen THEN RETURN NULL;END IF;
 RETURN states;
END $$;

CREATE FUNCTION fleet_configuration_metadata_valid(d jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE f jsonb;t jsonb;a text;seen text[]:='{}';prefix text:='^(module[.][A-Za-z_][A-Za-z0-9_-]*(\[(0|[1-9][0-9]*)\]|\["[A-Za-z0-9_-]+"\])?[.])*';suffix text:='[.][A-Za-z_][A-Za-z0-9_-]*(\[(0|[1-9][0-9]*)\]|\["[A-Za-z0-9_-]+"\])?$';ref text;dir text;BEGIN
 IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR NOT d ?& ARRAY['schema_version','authority','repository','pipeline','terraform'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d) k WHERE k<>ALL(ARRAY['schema_version','authority','repository','pipeline','terraform'])) OR d->'schema_version' IS DISTINCT FROM '"1"'::jsonb OR d->'authority' IS DISTINCT FROM '"TERRAFORM"'::jsonb THEN RETURN false;END IF;
 IF jsonb_typeof(d->'repository') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(d->'repository') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'string') THEN RETURN false;END IF;
 IF jsonb_typeof(d->'repository') IS DISTINCT FROM 'object' OR NOT (d->'repository') ?& ARRAY['url','ref','directory'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d->'repository') k WHERE k<>ALL(ARRAY['url','ref','directory'])) OR coalesce(d->'repository'->>'url','') !~ '^https://[^/?#@[:space:]]+(/[^?#[:space:]]*)?$' OR length(d->'repository'->>'url')>2048 OR coalesce(d->'repository'->>'ref','')='' OR length(d->'repository'->>'ref')>255 OR coalesce(d->'repository'->>'directory','')='' OR length(d->'repository'->>'directory')>512 THEN RETURN false;END IF;
 ref:=d->'repository'->>'ref';dir:=d->'repository'->>'directory';
 IF ref ~ '[[:space:][:cntrl:]~^:?*]' OR position(chr(92) IN ref)>0 OR position('[' IN ref)>0 OR position(']' IN ref)>0 OR left(ref,1) IN('-','/') OR right(ref,1)='/' OR position('..' IN ref)>0 OR position('@{' IN ref)>0 OR position('//' IN ref)>0 OR EXISTS(SELECT 1 FROM unnest(string_to_array(ref,'/')) part WHERE left(part,1)='.' OR right(part,1)='.' OR right(part,5)='.lock') OR dir ~ '[[:space:][:cntrl:]*:]' OR position(chr(92) IN dir)>0 OR left(dir,1)='/' OR right(dir,1)='/' OR position('//' IN dir)>0 OR (dir<>'.' AND EXISTS(SELECT 1 FROM unnest(string_to_array(dir,'/')) part WHERE part IN('.','..'))) OR position(chr(92) IN d->'repository'->>'url')>0 THEN RETURN false;END IF;
 IF jsonb_typeof(d->'pipeline') IS DISTINCT FROM 'object' OR NOT (d->'pipeline') ?& ARRAY['system','identity'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d->'pipeline') k WHERE k<>ALL(ARRAY['system','identity'])) OR coalesce(d->'pipeline'->>'system','') NOT IN('GITHUB_ACTIONS','GITLAB_CI','BITBUCKET_PIPELINES','OTHER') OR jsonb_typeof(d->'pipeline'->'system') IS DISTINCT FROM 'string' OR jsonb_typeof(d->'pipeline'->'identity') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(d->'pipeline'->'identity') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'string') OR NOT (d->'pipeline'->'identity') ?& ARRAY['issuer','audience','subject','pipeline_id'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d->'pipeline'->'identity') k WHERE k<>ALL(ARRAY['issuer','audience','subject','pipeline_id'])) OR d->'pipeline'->'identity'->>'audience' IS DISTINCT FROM 'finops-deployment-observer' OR coalesce(d->'pipeline'->'identity'->>'issuer','') !~ '^https://[^/?#@[:space:]]+(/[^?#[:space:]]*)?$' OR position(chr(92) IN d->'pipeline'->'identity'->>'issuer')>0 OR length(d->'pipeline'->'identity'->>'issuer')>2048 OR coalesce(d->'pipeline'->'identity'->>'subject','') !~ '^[^*[:space:][:cntrl:]]+$' OR length(d->'pipeline'->'identity'->>'subject')>512 OR coalesce(d->'pipeline'->'identity'->>'pipeline_id','') !~ '^[^*[:space:][:cntrl:]]+$' OR length(d->'pipeline'->'identity'->>'pipeline_id')>256 THEN RETURN false;END IF;
 f:=d->'terraform';
 IF jsonb_typeof(f) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(f) x WHERE x.key<>'traffic' AND jsonb_typeof(x.value) IS DISTINCT FROM 'string') THEN RETURN false;END IF;
 IF jsonb_typeof(f) IS DISTINCT FROM 'object' OR NOT f ?& ARRAY['workspace','state_lineage','asg_address','launch_template_address'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) k WHERE k<>ALL(ARRAY['workspace','state_lineage','asg_address','launch_template_address','traffic'])) OR coalesce(f->>'workspace','') !~ '^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$' OR coalesce(f->>'state_lineage','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR coalesce(f->>'asg_address','') !~ (prefix||'aws_autoscaling_group'||suffix) OR coalesce(f->>'launch_template_address','') !~ (prefix||'aws_launch_template'||suffix) OR length(f->>'asg_address')>512 OR length(f->>'launch_template_address')>512 THEN RETURN false;END IF;
 IF f ? 'traffic' THEN
  t:=f->'traffic';
  IF jsonb_typeof(t) IS DISTINCT FROM 'object' OR jsonb_typeof(t->'listener_rule_address') IS DISTINCT FROM 'string' OR EXISTS(SELECT 1 FROM jsonb_array_elements(t->'target_group_addresses') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string') THEN RETURN false;END IF;
  IF jsonb_typeof(t) IS DISTINCT FROM 'object' OR NOT t ?& ARRAY['listener_rule_address','target_group_addresses'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(t) k WHERE k<>ALL(ARRAY['listener_rule_address','target_group_addresses'])) OR coalesce(t->>'listener_rule_address','') !~ (prefix||'aws_lb_listener_rule'||suffix) OR length(t->>'listener_rule_address')>512 OR jsonb_typeof(t->'target_group_addresses') IS DISTINCT FROM 'array' OR jsonb_array_length(t->'target_group_addresses')<>2 THEN RETURN false;END IF;
  FOR a IN SELECT jsonb_array_elements_text(t->'target_group_addresses') LOOP
   IF coalesce(a,'') !~ (prefix||'aws_lb_target_group'||suffix) OR length(a)>512 OR a=ANY(seen) THEN RETURN false;END IF;seen:=array_append(seen,a);
  END LOOP;
 END IF;
 RETURN true;
END $$;

CREATE FUNCTION guard_fleet_configuration() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE r jsonb;rh text;v bigint;sv bigint;decl public.fleet_configuration_declarations%ROWTYPE;sc public.fleet_history_scopes%ROWTYPE;states jsonb;BEGIN
 IF NEW.tenant_id IS DISTINCT FROM current_setting('app.tenant_id',true) OR NOT pg_has_role(current_user,'finops_api','MEMBER') THEN RAISE EXCEPTION 'fleet configuration requires tenant API';END IF;
 NEW.writer_role:='finops_api';NEW.created_at:=clock_timestamp();
 IF jsonb_typeof(NEW.document) IS DISTINCT FROM 'object' OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document THEN RAISE EXCEPTION 'fleet configuration exact document hash differs';END IF;
 r:=public.fleet_configuration_registration(NEW.tenant_id,NEW.registration_id);
 SELECT content_hash INTO rh FROM public.fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id AND version=NEW.registration_version;
 IF r IS NULL OR rh IS NULL OR NEW.registration_version IS DISTINCT FROM (r->>'version')::bigint OR NEW.document->'schema_version' IS DISTINCT FROM '"1"'::jsonb OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->>'registration_id' IS DISTINCT FROM NEW.registration_id OR (NEW.document->>'registration_version')::bigint IS DISTINCT FROM NEW.registration_version OR NEW.document->>'registration_hash' IS DISTINCT FROM rh OR NEW.document->'binding' IS DISTINCT FROM r->'binding' OR NEW.document->>'fleet_id' IS DISTINCT FROM r->>'fleet_id' OR NEW.document->>'asg_arn' IS DISTINCT FROM r->>'asg_arn' OR NEW.workload_id IS DISTINCT FROM r->'binding'->>'workload_id' OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'estimated_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'reason_codes')>128 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.document->'reason_codes') c WHERE jsonb_typeof(c)<>'string' OR c#>>'{}' !~ '^[A-Z0-9_]{1,128}$') THEN RAISE EXCEPTION 'fleet configuration current group binding or no-authority seal differs';END IF;
 IF TG_TABLE_NAME='fleet_configuration_declarations' THEN
  IF NOT NEW.document ?& ARRAY['schema_version','id','version','registration_id','registration_version','registration_hash','fleet_id','asg_arn','binding','source_id','source_registration_version','source_config_hash','metadata','status','reason_codes','execution_authorized','estimated_saving','verified_saving','declared_by'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','version','registration_id','registration_version','registration_hash','fleet_id','asg_arn','binding','source_id','source_registration_version','source_config_hash','metadata','status','reason_codes','execution_authorized','estimated_saving','verified_saving','declared_by'])) THEN RAISE EXCEPTION 'fleet configuration declaration shape differs';END IF;
  SELECT coalesce(max(version),0)+1 INTO v FROM public.fleet_configuration_declarations WHERE tenant_id=NEW.tenant_id AND registration_id=NEW.registration_id;
  SELECT version INTO sv FROM public.source_registrations WHERE tenant_id=NEW.tenant_id AND id=r->>'source_id';
  IF NEW.version IS DISTINCT FROM v OR (NEW.document->>'version')::bigint IS DISTINCT FROM v OR NEW.document->>'source_id' IS DISTINCT FROM r->>'source_id' OR (NEW.document->>'source_registration_version')::bigint IS DISTINCT FROM sv OR NEW.document->>'source_config_hash' IS DISTINCT FROM r->>'source_config_hash' OR NEW.document->>'status' IS DISTINCT FROM 'DECLARED_NOT_ATTESTED' OR NEW.document->'reason_codes' IS DISTINCT FROM '["CONFIGURATION_ADDRESS_MAPPING_UNVERIFIED","CONFIGURATION_GIT_HEAD_UNOBSERVED","CONFIGURATION_STATE_UNOBSERVED","DECLARED_NOT_ATTESTED","PIPELINE_ATTESTATION_REQUIRED"]'::jsonb OR coalesce(NEW.document->>'declared_by','')='' OR length(NEW.document->>'declared_by')>512 OR NOT public.fleet_configuration_metadata_valid(NEW.document->'metadata') THEN RAISE EXCEPTION 'fleet configuration declaration metadata or CAS differs';END IF;
 ELSIF TG_TABLE_NAME='fleet_configuration_proposals' THEN
  IF NOT NEW.document ?& ARRAY['schema_version','id','purpose','registration_id','registration_version','registration_hash','binding','fleet_id','asg_arn','declaration_id','declaration_version','declaration_hash','scope_id','scope_hash','scope_reference_root','definition_id','definition_version','definition_hash','history_start','history_end','membership_status','observation_count','selected_observation_count','source_states','as_of','status','reason_codes','execution_authorized','estimated_saving','verified_saving','change_plan_id','proposed_by'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','purpose','registration_id','registration_version','registration_hash','binding','fleet_id','asg_arn','declaration_id','declaration_version','declaration_hash','scope_id','scope_hash','scope_reference_root','definition_id','definition_version','definition_hash','history_start','history_end','membership_status','observation_count','selected_observation_count','source_states','as_of','status','reason_codes','execution_authorized','estimated_saving','verified_saving','change_plan_id','proposed_by'])) THEN RAISE EXCEPTION 'fleet configuration proposal shape differs';END IF;
  SELECT * INTO decl FROM public.fleet_configuration_declarations WHERE tenant_id=NEW.tenant_id AND id=NEW.declaration_id;
  SELECT * INTO sc FROM public.fleet_history_scopes WHERE tenant_id=NEW.tenant_id AND id=NEW.scope_id;
  states:=public.fleet_configuration_scope_sources(NEW.tenant_id,NEW.registration_id,NEW.scope_id,(NEW.document->>'as_of')::timestamptz);
  IF decl.id IS NULL OR sc.id IS NULL OR states IS NULL OR decl.registration_id IS DISTINCT FROM NEW.registration_id OR decl.registration_version IS DISTINCT FROM NEW.registration_version OR decl.document->>'registration_hash' IS DISTINCT FROM rh OR decl.version IS DISTINCT FROM (SELECT max(version) FROM public.fleet_configuration_declarations WHERE tenant_id=NEW.tenant_id AND registration_id=NEW.registration_id) OR NEW.document->>'purpose' IS DISTINCT FROM 'FLEET_CONFIGURATION_PROPOSAL' OR NEW.document->>'declaration_id' IS DISTINCT FROM NEW.declaration_id OR (NEW.document->>'declaration_version')::bigint IS DISTINCT FROM decl.version OR NEW.document->>'declaration_hash' IS DISTINCT FROM decl.content_hash OR NEW.document->>'scope_id' IS DISTINCT FROM NEW.scope_id OR NEW.document->>'scope_hash' IS DISTINCT FROM sc.content_hash OR NEW.document->>'scope_reference_root' IS DISTINCT FROM sc.reference_root OR NEW.document->>'definition_id' IS DISTINCT FROM sc.definition_id OR (NEW.document->>'definition_version')::bigint IS DISTINCT FROM sc.definition_version OR NEW.document->>'definition_hash' IS DISTINCT FROM sc.document->>'definition_hash' OR NEW.document->'history_start' IS DISTINCT FROM sc.document->'start' OR NEW.document->'history_end' IS DISTINCT FROM sc.document->'end' OR NEW.document->'membership_status' IS DISTINCT FROM sc.document->'membership_status' OR NEW.document->'observation_count' IS DISTINCT FROM sc.document->'observation_count' OR NEW.document->'selected_observation_count' IS DISTINCT FROM sc.document->'selected_observation_count' OR NEW.document->'source_states' IS DISTINCT FROM states OR NEW.document->>'status' IS DISTINCT FROM 'BLOCKED' OR NEW.document->'change_plan_id' IS DISTINCT FROM 'null'::jsonb OR coalesce(NEW.document->>'proposed_by','')='' OR length(NEW.document->>'proposed_by')>512 THEN RAISE EXCEPTION 'fleet configuration proposal immutable scope or current authority differs';END IF;
  IF NOT (NEW.document->'reason_codes') ?& ARRAY['CONFIGURATION_ADDRESS_MAPPING_UNVERIFIED','CONFIGURATION_GIT_HEAD_UNOBSERVED','CONFIGURATION_STATE_UNOBSERVED','DECLARED_NOT_ATTESTED','FLEET_CAPACITY_UNPROVEN','FLEET_ECONOMICS_UNPROVEN','FLEET_EXECUTION_NOT_ENABLED','FLEET_OWNERSHIP_UNPROVEN','HISTORICAL_MEMBERSHIP_INTERVAL_OWNERSHIP_UNPROVEN','PIPELINE_ATTESTATION_REQUIRED','WORK_PRESERVATION_UNPROVEN'] OR NOT (NEW.document->'reason_codes') @> (sc.document->'reason_codes') OR ((sc.document->>'selected_observation_count')::integer=0 AND NOT (NEW.document->'reason_codes') ? 'GROUP_MEMBERSHIP_UNOBSERVED') OR (EXISTS(SELECT 1 FROM jsonb_array_elements(states) s WHERE s->>'status'<>'ACTIVE') AND NOT (NEW.document->'reason_codes') ? 'FLEET_CONFIGURATION_SOURCE_NOT_HEALTHY') THEN RAISE EXCEPTION 'fleet configuration missing evidence blockers differ';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_configuration_declarations_writer BEFORE INSERT ON fleet_configuration_declarations FOR EACH ROW EXECUTE FUNCTION guard_fleet_configuration();
CREATE TRIGGER fleet_configuration_proposals_writer BEFORE INSERT ON fleet_configuration_proposals FOR EACH ROW EXECUTE FUNCTION guard_fleet_configuration();
REVOKE ALL ON FUNCTION fleet_configuration_registration(text,text),fleet_configuration_scope_sources(text,text,text,timestamptz),fleet_configuration_metadata_valid(jsonb),guard_fleet_configuration() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_configuration_registration(text,text),fleet_configuration_scope_sources(text,text,text,timestamptz),fleet_configuration_metadata_valid(jsonb) TO finops_api,finops_ingester;
